SELECT 'payments.chk_payments_target' AS check_item, CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='payments' AND constraint_name='chk_payments_target' AND constraint_type='CHECK') AS CHAR) AS live_value
UNION ALL SELECT 'payments.chk_payment_type', CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='payments' AND constraint_name='chk_payments_payment_type' AND constraint_type='CHECK') AS CHAR)
UNION ALL SELECT 'plans.chk_price', CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='subscription_plans' AND constraint_name='chk_subscription_plans_price' AND constraint_type='CHECK') AS CHAR)
UNION ALL SELECT 'plans.chk_currency_VND', CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='subscription_plans' AND constraint_name='chk_subscription_plans_currency' AND constraint_type='CHECK') AS CHAR)
UNION ALL SELECT 'plans.chk_max_books', CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='subscription_plans' AND constraint_name='chk_subscription_plans_max_books' AND constraint_type='CHECK') AS CHAR)
UNION ALL SELECT 'plans.chk_max_days', CAST((SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='subscription_plans' AND constraint_name='chk_subscription_plans_max_days_per_book' AND constraint_type='CHECK') AS CHAR)
UNION ALL SELECT 'payments.target_FK_columns', CAST((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payments' AND column_name IN ('book_loan_id','subscription_id','fine_id')) AS CHAR)
UNION ALL SELECT 'payments.payment_type', COALESCE((SELECT column_type FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payments' AND column_name='payment_type'), 'MISSING')
UNION ALL SELECT 'legacy payment rows', CAST((SELECT COUNT(*) FROM library_db1.payments WHERE payment_type IN ('LOST_BOOK_PENALTY','DAMAGED_BOOK_PENALTY')) AS CHAR)